// Fact-check triggers and model settings come from CONTROL config.
// cfg.fact_check = { trigger_categories:[], number_pattern, verify_tag,
//                    claim_model, claim_temperature, claim_max_tokens, claim_system_prompt,
//                    verify_model, verify_max_tokens, verify_system_prompt }
const item = $input.item.json;
const cfg = item.cfg || {};
const f = cfg.fact_check || {};

const triggerCategories = f.trigger_categories || ['news', 'data', 'report'];
const verifyTag = (f.verify_tag !== undefined) ? f.verify_tag : '[VERIFY]';
const numberPattern = f.number_pattern || '\\d+%|\\$\\d|\\d+ (million|billion|thousand|percent)';

const category = (item['Category'] || '').toLowerCase();
const script = item['Script'] || '';

const isNews = triggerCategories.some(c => category.includes(String(c).toLowerCase()));
let hasNumbers = false;
try { hasNumbers = new RegExp(numberPattern, 'i').test(script); }
catch (e) { console.log('[2] Invalid number_pattern in config: ' + e.message); }
const hasVerifyTags = verifyTag ? script.includes(verifyTag) : false;
const needsFactCheck = isNews || hasNumbers || hasVerifyTags;

return { json: {
  cfg: cfg,
  record_id: item.id || '',
  topic: item['Topic'] || '',
  category: item['Category'] || 'General',
  script: script,
  source_url: item['Source URL'] || '',
  platform: item['Platform'] || 'YouTube',
  content_type: item['Content Type'] || 'Video',
  needs_fact_check: needsFactCheck,
  claim_model: f.claim_model || 'gpt-4.1-mini',
  claim_temperature: (f.claim_temperature !== undefined && f.claim_temperature !== null) ? f.claim_temperature : 0.1,
  claim_max_tokens: f.claim_max_tokens || 1500,
  claim_system_prompt: f.claim_system_prompt || 'You are a fact-checking assistant. Extract ALL factual claims from the script that need verification. Return a JSON object with: claims (array of {claim_text, claim_type, search_query}). If no claims, return {"claims": []}. Return ONLY valid JSON.',
  verify_model: f.verify_model || 'sonar',
  verify_max_tokens: f.verify_max_tokens || 2000,
  verify_system_prompt: f.verify_system_prompt || "You are a fact-checking assistant. For each claim, determine if it is VERIFIED, UNVERIFIED, or FALSE. Provide source URLs. Return JSON with: results (array of {claim_number, status, source_url, notes}), overall_status ('Verified'/'Failed'/'Partial'), source_links (comma-separated URLs). Return ONLY valid JSON."
} };

