const response = $input.item.json;
const sourceData = $('2. Extract & Evaluate Record').item.json;

// A failed or unusable extraction is never 'no claims'. It is flagged and sent to review.
const fail = (reason) => ({ json: { ...sourceData, claims: [], all_verified: true, extraction_failed: true, verification_results: 'FACT CHECK DID NOT RUN - ' + reason + ' Manual review needed.', source_links: '' } });

if (response.error || !response.choices || !response.choices[0] || !response.choices[0].message) {
  const msg = typeof response.error === 'string' ? response.error : JSON.stringify(response.error || 'no choices returned');
  return fail('Claim extraction call failed: ' + msg + '.');
}

let claimsData = null;
try {
  const content = response.choices[0].message.content;
  const cleanContent = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  claimsData = JSON.parse(cleanContent);
} catch (e) {
  return fail('Claim extraction returned unparseable output.');
}

if (!claimsData || !Array.isArray(claimsData.claims)) {
  return fail('Claim extraction returned no claims array.');
}

if (claimsData.claims.length === 0) {
  return { json: { ...sourceData, claims: [], all_verified: true, extraction_failed: false, verification_results: 'No factual claims extracted from script - sent to review.', source_links: '' } };
}

const claimsList = claimsData.claims.map((c, i) => `${i+1}. ${c.claim_text} [Search: ${c.search_query}]`).join('\n');

return { json: { ...sourceData, claims: claimsData.claims, claims_text: claimsList, all_verified: false, extraction_failed: false, verification_results: '', source_links: '' } };

const response = $input.item.json;
const sourceData = $('5. Parse Claims').item.json;

let verificationData = {};
try {
  const content = response.choices[0].message.content;
  const cleanContent = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  verificationData = JSON.parse(cleanContent);
} catch (e) {
  verificationData = { overall_status: 'Manual Review Needed', source_links: '', results: [] };
}

const overallStatus = verificationData.overall_status || 'Manual Review Needed';
const sourceLinks = verificationData.source_links || '';

let summary = '';
if (verificationData.results && verificationData.results.length > 0) {
  summary = verificationData.results.map(r =>
    `Claim ${r.claim_number}: ${r.status} - ${r.notes || ''} ${r.source_url ? '(' + r.source_url + ')' : ''}`
  ).join('\n');
}

let airtableStatus = 'Verified'; // Status field value
let factCheckStatus = 'Passed'; // Fact_Check_Status field value
if (overallStatus === 'Failed') { airtableStatus = 'Failed'; factCheckStatus = 'Failed'; }
else if (overallStatus === 'Partial' || overallStatus === 'Manual Review Needed') { airtableStatus = 'Needs Review'; factCheckStatus = 'In Review'; }

return { json: {
  cfg: sourceData.cfg || {},
  record_id: sourceData.record_id,
  fact_check_status: airtableStatus,
  fact_check_status_field: factCheckStatus,
  verification_summary: summary,
  source_links: sourceLinks,
  overall_status: overallStatus
} };

// Reached when no claims were verified: either extraction failed or it returned zero claims.
// Neither case may resolve to Verified, so the review state is set explicitly.
const sourceData = $input.item.json;
return { json: {
  cfg: sourceData.cfg || {},
  record_id: sourceData.record_id,
  fact_check_status: 'Needs Review',
  fact_check_status_field: 'In Review',
  verification_summary: sourceData.verification_results || 'No factual claims extracted from script - sent to review.',
  source_links: '',
  overall_status: sourceData.extraction_failed ? 'Extraction Failed' : 'No Claims'
} };

// Swappable config comes from CONTROL as JSON.
// Clients.Config_JSON = client-wide defaults.
// Client_Outputs.Config_JSON where Key = '{Client}::script' = per-output override (shallow merge, output wins).
const OUTPUT_TYPE = 'script';

function parseJson(raw, label) {
  if (!raw) return {};
  try {
    const v = JSON.parse(raw);
    if (v && typeof v === 'object' && !Array.isArray(v)) return v;
    console.log('[0b] Config_JSON on ' + label + ' is not an object, ignoring');
    return {};
  } catch (e) {
    console.log('[0b] Invalid Config_JSON on ' + label + ': ' + e.message);
    return {};
  }
}

const outputs = $input.all().map(i => i.json);
const clients = $('0a. Load Clients').all().map(i => i.json);

const outByKey = {};
for (const o of outputs) {
  const key = (o['Key'] || '').trim().toLowerCase();
  if (key) outByKey[key] = o;
}

const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Video_Enabled'] !== true) continue;
  if (!c['Video_Base_ID']) { console.log('[0b] ' + name + ' has no Video_Base_ID, skipping'); continue; }

  const clientCfg = parseJson(c['Config_JSON'], name);
  const o = outByKey[(name + '::' + OUTPUT_TYPE).toLowerCase()] || null;
  const outputCfg = o ? parseJson(o['Config_JSON'], name + '::' + OUTPUT_TYPE) : {};
  const merged = { ...clientCfg, ...outputCfg };

  out.push({ json: {
    ...merged,
    client_name:     name,
    video_base_id:   c['Video_Base_ID'],
    brand_name:      c['Brand_Name'] || name,
    notes_stage_tag: c['Notes_Stage_Tag'] || '',
    output_type:     OUTPUT_TYPE
  } });
}

console.log('[0b] Clients to process: ' + out.length);
return out;

const loop = $('0c. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.video_base_id) { throw new Error('Could not resolve client config for this iteration.'); }
return { json: { ...$input.item.json, cfg } };
